  "3194": { "hanzi": "他太固执，不肯改变主意。", "pinyin": "Tā tài gùzhi, bù kěn gǎibiàn zhǔyi.", "meaning": "He is too stubborn to change his mind." },
  "3830": { "hanzi": "周末我们全家人去湖上划船游玩。", "pinyin": "Zhōumò wǒmen quán jiā rén qù hú shàng huáchuán yóuwán.", "meaning": "On weekend our whole family went rowing on lake." },
